        # Merge average headings for all rays in a collision component.
        for x in active:
            if id(x) in collided:
                others=[y for y in active if id(y) in collided and y is not x and (proposed[id(y)]==proposed[id(x)] or (proposed[id(y)]==x['cell'] and proposed[id(x)]==y['cell']))]
                if others:
                    # pairwise in these tasks
