            q=nxt(x) if id(x) in collided else proposed[id(x)]
            if not(0<=q[0]<h and 0<=q[1]<w):
                x['active']=False; continue
            dr,dc=x['d']; r,c=x['p']; x['p']=(r+dr,c+dc); x['cell']=q
            a[q[0]][q[1]]=x['color']
    return a

